uth_example:
RISKY = {"delete_file"}
plan = [("search", {"q": "flights"}, 3), ("search", {"q": "flights"}, 3),
        ("search", {"q": "flights"}, 3), ("delete_file", {"path": "notes"}, 1)]
max_cents, max_repeats = 8, 2
spent, seen, log = 0, {}, []

def approver(tool, args):
    return False          # a human said no

for tool, args, cost in plan:
    if spent + cost > max_cents:
        log.append("STOP: budget"); break
    sig = (tool, tuple(sorted(args.items())))
    seen[sig] = seen.get(sig, 0) + 1
    if seen[sig] > max_repeats:
        log.append("STOP: loop on " + tool); break
    if tool in RISKY and not approver(tool, args):
        log.append("BLOCKED " + tool); continue
    spent += cost
    log.append(f"ran {tool} ({cost}c)")

print(log, "spent:", spent)
